#!/usr/bin/env bash
# .verify.sh — L0 ground-truth gate (auto-generated by gen-verify-gate.sh).
# Runs every one of the repo's real checks in order, then exits non-zero if any
# failed. Regenerate with: ~/.hermes/scripts/gen-verify-gate.sh
#
# HONESTY CONTRACT: this gate only runs checks that exist. It does NOT invent
# a test suite. If a repo has no runnable checks it exits 1 on purpose so a
# missing gate can never look like a passing one.
set -uo pipefail
cd "$(dirname "$0")"

FAILED=0
run_step() {  # run_step <label> <cmd...>
  local label="$1"; shift
  echo "── $label ──"
  if "$@"; then
    echo "   ✓ $label"
  else
    rc=$?
    echo "   ✗ $label (exit $rc)"
    FAILED=1
    return $rc
  fi
}

# Python tool runner: prefer the repo's .venv, then .venv-lancedb, then PATH.
# PYTHONPATH/VIRTUAL_ENV are unset so the Hermes runtime's site-packages can't
# shadow the repo venv (this pollution bit the fleet index before).
run_py_tool() {  # run_py_tool <tool> <args...>
  local tool="$1"; shift
  if [ -x ".venv/bin/$tool" ]; then env -u PYTHONPATH -u VIRTUAL_ENV ".venv/bin/$tool" "$@"; return $?; fi
  if [ -x ".venv-lancedb/bin/$tool" ]; then env -u PYTHONPATH -u VIRTUAL_ENV ".venv-lancedb/bin/$tool" "$@"; return $?; fi
  if command -v "$tool" >/dev/null 2>&1; then env -u PYTHONPATH -u VIRTUAL_ENV "$tool" "$@"; return $?; fi
  # No console script on PATH (common for pytest on macOS): try the module form.
  if python3 -c "import $tool" >/dev/null 2>&1; then env -u PYTHONPATH -u VIRTUAL_ENV python3 -m "$tool" "$@"; return $?; fi
  echo "   (tool '$tool' not found — install it or point .venv at it)"
  return 127
}

# Syntax checks over tracked files (read-only; skips vendored and build dirs).
tracked_src() {  # tracked_src <pathspec...>
  git ls-files -- "$@" | grep -v -E '(^|/)(node_modules|vendor|dist|build|debug|\.venv[^/]*|uncommitted)/|\.min\.js$'
}
syntax_php() {
  # WPCode / Code Snippets files are pasted without an opening <?php tag. A file that starts with
  # PHP code (not "<?" and not an HTML/template "<") is linted through stdin with the tag added;
  # otherwise php -l reads the code as HTML and checks nothing. A leading BOM is ignored.
  local f rc=0 out first
  while IFS= read -r f; do
    [ -n "$f" ] || continue
    first="$(LC_ALL=C sed $'1s/^\xEF\xBB\xBF//' "$f" | grep -m1 -v '^[[:space:]]*$')"
    case "$first" in
      '<'*) out="$(LC_ALL=C sed $'1s/^\xEF\xBB\xBF//' "$f" | php -l 2>&1)" ;;
      *)    out="$({ echo '<?php'; LC_ALL=C sed $'1s/^\xEF\xBB\xBF//' "$f"; } | php -l 2>&1)" ;;
    esac
    echo "$out" | grep -q '^No syntax errors' || { echo "   php -l: $f"; echo "$out" | grep -v '^$' | head -2; rc=1; }
  done < <(tracked_src '*.php')
  return $rc
}
newest_python() {  # newest python3.x on PATH (the parse must accept the newest syntax the code uses)
  local v
  for v in python3.14 python3.13 python3.12 python3.11 python3.10; do
    command -v "$v" >/dev/null 2>&1 && { echo "$v"; return; }
  done
  echo python3
}
syntax_py() {
  local py; py="$(newest_python)"
  [ -x .venv/bin/python ] && py=.venv/bin/python
  tracked_src '*.py' | env -u PYTHONPATH -u VIRTUAL_ENV "$py" -c 'import ast, sys
bad = 0
for f in sys.stdin.read().splitlines():
    try:
        ast.parse(open(f, "rb").read(), f)
    except SyntaxError as e:
        print("   python:", f, e); bad = 1
sys.exit(bad)'
}
syntax_js() {
  local f rc=0
  while IFS= read -r f; do
    [ -n "$f" ] || continue
    node --check "$f" >/dev/null 2>&1 || { echo "   node --check: $f"; node --check "$f" 2>&1 | grep -v '^$' | head -3; rc=1; }
  done < <(tracked_src '*.js' '*.mjs' '*.cjs')
  return $rc
}

run_step "npm run lint" npm run lint
run_step "npm run test" npm run test
run_step "npm run build" npm run build

if [ "$FAILED" -eq 0 ]; then
  echo "verify: PASS"
  exit 0
else
  echo "verify: FAIL"
  exit 1
fi
